def get_access_token(client_id, client_secret, token_url):
    response = requests.post(
        token_url,
        data={
            "grant_type": "client_credentials",
            "client_id": client_id,
            "client_secret": client_secret,
        },
        timeout=10,
    )
    response.raise_for_status()
    return response.json()["access_token"]

def get_all_indicators(base_url, headers):
    all_items = []
    params = {"page_size": 100}
    while True:
        r = requests.get(base_url, headers=headers, params=params, timeout=10)
        r.raise_for_status()
        payload = r.json()
        all_items.extend(payload["results"])
        next_token = payload.get("next_page_token")
        if not next_token:
            break
        params["page_token"] = next_token
    return all_items

def get_with_backoff(url, headers, params, max_retries=5):
    delay = 1
    for attempt in range(max_retries):
        r = requests.get(url, headers=headers, params=params, timeout=10)
        if r.status_code == 429:
            retry_after = int(r.headers.get("Retry-After", delay))
            time.sleep(retry_after)
            delay *= 2
            continue
        r.raise_for_status()
        return r.json()
    raise RuntimeError(f"Exceeded {max_retries} retries against {url}")
